INSERT INTO `wp_postmeta` VALUES (213,7,'about_text','O ITK Treinamentos é especializado em treinamento comportamental, desenvolvimento pessoal e crescimento, com a missão de ajudar os participantes a se conscientizarem de sua missão neste mundo. Nossos programas visam destacar as repercussões, tanto positivas quanto negativas, de cada ação, palavra e gesto, capacitando-os para gerar impactos significativos.\r\n\r\nAcreditamos no poder transformador das pessoas e buscamos guiá-las em sua jornada de autodescoberta e autodesenvolvimento, capacitando-as a criar um futuro mais promissor para si mesmas e para a sociedade como um todo.');
INSERT INTO `wp_postmeta` VALUES (214,7,'_about_text','field_about_text');
