INSERT INTO `wp_postmeta` VALUES (1181,260,'testi_desc','Para pessoas que desejam encontrar seu propósito de vida e estão interessados em melhorar seu desenvolvimento emocional, pessoal e profissional. O ITK Treinamentos tem como principal objetivo direcionar as pessoas em uma jornada de descoberta e utilização de seu potencial interior, com foco no gerenciamento das emoções.');
