INSERT INTO `wp_postmeta` VALUES (2783,305,'team_text','Nossa equipe de terapeutas é apaixonada por ajudar pessoas a alcançar o bem-estar. Com experiência e compromisso, eles oferecem suporte terapêutico personalizado para promover transformação e crescimento pessoal.');
